import numpy as np

def _pp(n, p_in, p_out, seed):
    U = np.random.default_rng(seed).random((n, n))
    y = (np.arange(n) >= n // 2).astype(int)
    P = np.where(y[:, None] == y[None, :], p_in, p_out)
    A = np.triu((U < P).astype(float), 1)
    return A + A.T, y

def _feat(y, shift, seed):
    X = np.random.default_rng(seed).standard_normal((len(y), 2))
    X[:, 0] += shift * (2 * np.asarray(y) - 1)
    return X

def _edges(A):
    return [(int(i), int(j)) for i, j in zip(*np.nonzero(np.triu(A, 1)))]

def _acc(pred, y, tr):
    other = np.setdiff1d(np.arange(len(y)), tr)
    return float(np.mean(np.asarray(pred)[other] == np.asarray(y)[other]))

